import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // ============================================================================
  // 2. LOAD TEXTURE & APPLY
  // ============================================================================
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((texture) => {
      material.colorNode = new (require('three/tsl')).uniform(texture);
      material.needsUpdate = true;
    })
    .catch(() => {
      // Fallback: solid paper color if load fails
      material.color.setHex(0xe8ecf2);
    });

  // ============================================================================
  // 3. POSITION & ROTATION
  // ============================================================================
  mesh.position.set(
    config.scenePosition?.x ?? 2.5,
    config.scenePosition?.y ?? 0.7,
    config.scenePosition?.z ?? 0
  );
  mesh.rotation.order = 'YXZ';

  // ============================================================================
  // 4. CINEMATIC PRIMITIVES
  // ============================================================================
  const primitiveRefs = [];

  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll' && prim.trigger === 'scroll') {
        const ref = ctx.primitives['parallax-scroll'](mesh, prim.params ?? {});
        primitiveRefs.push(ref);
      }
    }
  }

  // ============================================================================
  // 5. INTERACTION STATE
  // ============================================================================
  let isHovering = false;
  let hoverTimeline = null;
  let pressTimeline = null;

  // ============================================================================
  // 6. EVENT HANDLERS
  // ============================================================================
  const handlers = {
    onPointerEnter: () => {
      if (isHovering) return;
      isHovering = true;

      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      // rise-in: y +0.15 units, power3.out easing, 0.7s duration (subtle variant)
      hoverTimeline.to(
        mesh.position,
        {
          y: mesh.position.y + 0.15,
          duration: 0.7,
          ease: 'power3.out',
        },
        0
      );
    },

    onPointerLeave: () => {
      isHovering = false;

      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      // settle back
      const originalY = config.scenePosition?.y ?? 0.7;
      hoverTimeline.to(
        mesh.position,
        {
          y: originalY,
          duration: 0.9,
          ease: 'power4.out',
          overwrite: 'auto',
        },
        0
      );
    },

    onPointerDown: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();

      // press-down: scale 0.97, 120ms, back.out
      pressTimeline.to(
        mesh.scale,
        {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out',
        },
        0
      );
    },

    onPointerUp: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();

      // settle scale back to 1
      pressTimeline.to(
        mesh.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power4.out',
        },
        0
      );
    },

    onClick: () => {
      ctx.emit('hub-journal.select', {});
    },
  };

  // ============================================================================
  // 7. ATTACH HANDLERS TO MESH
  // ============================================================================
  mesh.userData.handlers = handlers;

  // ============================================================================
  // 8. CLEANUP
  // ============================================================================
  mesh.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    for (const ref of primitiveRefs) {
      if (ref && ref.cleanup) ref.cleanup();
    }

    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
